insert into public.dev_tracker (key, area, title, detail, status, next_step, sort_order, designed, built, tests_passed, merged, deployed, operational, awaiting) values
  ('social-home', 'Social Ecosystem', 'Home: "Your world. Your connections."', 'One home for every member: My Story, Business, Life, Love and Elite shortcuts; a composer (Photo, Video, Event, Thought); the Daily Journey card ("Who are you becoming?" → Talk to Journey); and the Connection Feed below. Bottom navigation: Home, Discover, Connect, Journey, Profile.', 'designed', 'Owner: confirm build order. Build after profiles and photos.', 500, true, false, false, false, false, false, 'owner'),
  ('social-profiles-photos', 'Social Ecosystem', 'Member profiles and photo galleries', 'Personal profiles with photographs (configurable limits per membership), visibility settings, moderation, anti-catfishing checks and storage-level privacy. Elite badge beside names. Foundation for everything else.', 'designed', 'Build first.', 501, true, false, false, false, false, false, null),
  ('social-feed', 'Social Ecosystem', 'The Connection Feed', 'Members share photographs, videos, thoughts, accomplishments, life updates and educational content; Appreciate, Discuss and Save; follow, connect and private messages. Audience controls per post (society, circle, connections). Reporting and moderation.', 'designed', 'Build after profiles.', 502, true, false, false, false, false, false, null),
  ('social-video', 'Social Ecosystem', 'Short videos and stories', 'Short educational, inspirational and lifestyle videos and stories, with moderation and storage limits.', 'designed', 'Later phase (storage and moderation costs need owner approval).', 503, true, false, false, false, false, false, 'owner'),
  ('social-circles', 'Social Ecosystem', 'Find Your Circle (interest communities)', 'Communities such as The World Explorers, The Visionaries, The Conscious Collective, The Social Sophisticates and The Authentic Connections. Each circle has its own feed, discussions, events, members, resources and travel plans; personalized recommendations from interests and personal discovery; no ranking of people.', 'designed', 'Build after the feed.', 504, true, false, false, false, false, false, null),
  ('social-calendar', 'Social Ecosystem', 'Connect Calendar: "What''s happening?"', 'Members and the platform share events: Business, Social, Singles, Couples, Travel & Adventures, Education & Webinars, Health & Wellness and Elite Experiences. Every event has I''m going, I''m interested, Looking for someone to attend with, and I''d like more information, plus Discuss, Share and Save. Builds on the existing webinar calendar.', 'designed', 'Build with circles.', 505, true, false, false, false, false, false, null),
  ('social-couples-connection', 'Social Ecosystem', 'The Couples Connection', 'Couples dashboard: Meet Other Couples, Travel Together, Double Dates, Couples Discussions, Local Connections, Shared Experiences, Couples Supporting Couples, Discover Adventures. Both partners 21+.', 'designed', 'Build with the couples experience.', 506, true, false, false, false, false, false, null),
  ('social-couples-travel', 'Social Ecosystem', 'The Couples Travel Exchange', 'Trip posts, recommendation requests, shared itineraries, resort and excursion recommendations, group vacations and inviting other couples, coordinated through the Connect Calendar. Travel safety guidance; no paid bookings without owner approval.', 'designed', 'Build after the Couples Connection.', 507, true, false, false, false, false, false, null)
